def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive = []
    prev_bids = []
    opp_budgets = []
    opp_urgent = 0
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            opp_budgets.append(opp.get('budget', 0))
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
                opp_urgent += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                prev_bids.append(prev.get('bid', 0))

    if not alive:
        return max(0.0, min(budget, DAILY_SALARY * 0.25))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0
    max_opp_budget = max(opp_budgets) if opp_budgets else 0.0

    tight_supply = supply <= 17
    loose_supply = supply >= 22

    if hp <= 2 or no_water >= 2:
        bid = max(DAILY_SALARY * 1.15, highest_prev + 3.0)
    elif hp <= 4 or no_water >= 1:
        if tight_supply:
            bid = max(DAILY_SALARY * 0.95, highest_prev + 2.0)
        else:
            bid = max(DAILY_SALARY * 0.82, avg_prev * 0.92)
    else:
        if highest_prev >= 110:
            bid = DAILY_SALARY * (0.28 if loose_supply else 0.38)
        elif highest_prev >= 90:
            bid = DAILY_SALARY * (0.34 if loose_supply else 0.48)
        else:
            bid = max(DAILY_SALARY * 0.42, highest_prev * 0.72)

    if opp_urgent >= 2 and hp > 4:
        bid *= 0.88
    if tight_supply:
        bid *= 1.12
    if loose_supply:
        bid *= 0.9

    if budget < DAILY_SALARY * 2:
        bid *= 0.82
    elif budget > max_opp_budget + 120 and (hp <= 4 or no_water >= 1):
        bid *= 1.08

    if day >= 8 and hp > 5 and no_water == 0:
        bid *= 0.9

    bid = max(0.0, min(budget, bid))
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    alive_opps = [o for o in opponents_status.values() if o.get('alive', False)]
    if not alive_opps:
        return max(0.0, min(budget, DAILY_SALARY * 0.45))

    # Estimate opponent pressure from yesterday trace bids.
    prev_bids = []
    for opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    # Baseline bid target: slightly under yesterday's typical high bids.
    if prev_bids:
        prev_bids_sorted = sorted(prev_bids)
        # Use a robust high percentile to avoid being too low.
        idx = int(len(prev_bids_sorted) * 0.75)
        if idx >= len(prev_bids_sorted):
            idx = len(prev_bids_sorted) - 1
        target = prev_bids_sorted[idx]
        # Undercut to win while reducing cost.
        bid = target - 3.0
    else:
        bid = DAILY_SALARY * 0.55

    # If supply is low, water is scarcer; increase bid modestly.
    # supply in [15,25], so normalize scarcity.
    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY) if MAX_SUPPLY != MIN_SUPPLY else 0.5
    if scarcity < 0.0:
        scarcity = 0.0
    if scarcity > 1.0:
        scarcity = 1.0
    bid *= (1.0 + 0.25 * scarcity)

    # If we're at risk (multiple no-water days or low hp), bid more.
    if hp <= 2.0:
        bid = max(bid, DAILY_SALARY * 0.9)
    elif hp <= 4.0 or no_water_days >= 2:
        bid = max(bid, DAILY_SALARY * 0.7)
    else:
        # Healthy: keep spending controlled.
        bid = min(bid, DAILY_SALARY * 0.65)

    # Never exceed budget.
    if budget <= 0.0:
        return 0.0
    bid = max(0.0, min(budget, bid))

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    supply = day_context['supply']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_status['budget'], 20.0)

    yesterday_bids = [o['previous_trace']['bid'] for o in alive_opponents if o.get('previous_trace') and o['previous_trace'].get('bid') is not None]

    if my_status['hp'] <= 3:
        return min(my_status['budget'], DAILY_SALARY * 1.1)

    if yesterday_bids:
        max_prev = max(yesterday_bids)
        if supply < 18:
            return min(my_status['budget'], max_prev + 5.0)
        return min(my_status['budget'], max(DAILY_SALARY * 0.4, max_prev * 0.8))

    return min(my_status['budget'], DAILY_SALARY * 0.5)
